6	)
7	
8	type RequestEditorFunc func(ctx context.Context, req *http.Request) error
9	
10	type RequestOption func(*requestOptions)
11	
12	type requestOptions struct {
13		headers map[string]string
14		editors []RequestEditorFunc
15	
16		noRetry bool
17	
18		retryPolicy       *RetryPolicy
19		responseSizeLimit responseSizeLimitOption
20	}
21	
22	func WithHeader(key, value string) RequestOption {
23		return func(o *requestOptions) {
24			if o.headers == nil {
25				o.headers = make(map[string]string)
26			}
27			o.headers[key] = value
28		}
29	}
30	
31	func WithRequestEditor(fn RequestEditorFunc) RequestOption {
32		return func(o *requestOptions) {
33			if fn == nil {
34				return
35			}
36			o.editors = append(o.editors, fn)
37		}
38	}
39	
40	func WithNoRetry() RequestOption {
41		return func(o *requestOptions) {
42			o.noRetry = true
43		}
44	}
45	
46	func WithRetryPolicy(policy RetryPolicy) RequestOption {
47		return func(o *requestOptions) {
48			o.retryPolicy = &policy
49		}
50	}
51	
52	func WithResponseSizeLimit(limit int64) RequestOption {
53		return func(o *requestOptions) {
54			o.responseSizeLimit = responseSizeLimitOption{
55				set:   true,
56				limit: limit,
57			}
58		}
59	}
60	
61	func WithNoResponseSizeLimit() RequestOption {
62		return func(o *requestOptions) {
63			o.responseSizeLimit = responseSizeLimitOption{
64				set:       true,
65				unlimited: true,
66			}
67		}
68	}
69	
70	func ApplyRequestOptions(ctx context.Context, opts ...RequestOption) (context.Context, []RequestEditorFunc) {
71		if ctx == nil {
72			ctx = context.Background()
73		}
74	
75		var o requestOptions
76		for _, opt := range opts {
77			if opt == nil {
78				continue
79			}
80			opt(&o)
81		}
82	
83		if o.noRetry {
84			ctx = withNoRetry(ctx)
85		}
86		if o.retryPolicy != nil {
87			ctx = withRetryPolicy(ctx, *o.retryPolicy)
88		}
89		if o.responseSizeLimit.set {
90			ctx = withResponseSizeLimit(ctx, o.responseSizeLimit)
91		}
92	
93		editors := make([]RequestEditorFunc, 0, len(o.editors)+1)
94		if len(o.headers) > 0 {
95			headers := make(map[string]string, len(o.headers))
96			for k, v := range o.headers {
97				headers[k] = v
98			}
99			editors = append(editors, func(_ context.Context, req *http.Request) error {
100				for k, v := range headers {
101					req.Header.Set(k, v)
102				}
103				return nil
104			})
105		}
106		editors = append(editors, o.editors...)
107	
108		return ctx, editors
109	}
