56	func NewClient(cfg pipedrive.Config) (*Client, error) {
57		baseURL := cfg.BaseURL
58		if baseURL == "" {
59			baseURL = DefaultBaseURL
60		}
61		// Ensure the HTTP client pins credentials to the resolved origin even
62		// when the caller relied on the default base URL.
63		cfg.BaseURL = baseURL
64	
65		httpClient := pipedrive.NewHTTPClient(cfg)
66	
67		raw, err := pipedrive.NewRawClient(baseURL, httpClient)
68		if err != nil {
69			return nil, err
70		}
71	
72		gen, err := genv1.NewClientWithResponses(baseURL, genv1.WithHTTPClient(httpClient))
73		if err != nil {
74			return nil, err
75		}
76	
77		oauthBaseURL := cfg.OAuthBaseURL
78		if oauthBaseURL == "" {
79			oauthBaseURL = DefaultOAuthBaseURL
80		}
81		// The OAuth endpoints authenticate with explicit client credentials,
82		// so their HTTP client carries no Auth provider.
83		oauthCfg := cfg
84		oauthCfg.Auth = nil
85		oauthCfg.BaseURL = oauthBaseURL
86		oauthRaw, err := pipedrive.NewRawClient(oauthBaseURL, pipedrive.NewHTTPClient(oauthCfg))
87		if err != nil {
88			return nil, err
89		}
90	
91		c := &Client{
92			Raw:   raw,
93			OAuth: &OAuthService{raw: oauthRaw, baseURL: oauthBaseURL},
94			gen:   gen,
95		}
96		c.Currencies = &CurrenciesService{client: c}
97		c.ActivityTypes = &ActivityTypesService{client: c}
