108		c.Persons = &PersonsService{client: c}
109		c.OrganizationFields = &OrganizationFieldsService{client: c}
110		c.Organizations = &OrganizationsService{client: c}
111		c.ProductFields = &ProductFieldsService{client: c}
112		c.Products = &ProductsService{client: c}
113		c.Files = &FilesService{client: c}
